const tutor = { id: "tutor-001", title: "T", status: "active", scope: { chapterIds: ["chapter-001"], sectionIds: ["s1"], description: "1" }, keyPoints: [], attempts: [], transcript: [] };
const targetFor = { learn: section, exam, tutor };

