export function planExamReviewPackets(exam: ScholarExam, questions: ExamQuestion[], book: ScholarBook): ReviewPacket[] {
  const packets: ReviewPacket[] = [];
  const sectionsById = new Map(book.chapters.flatMap((c) => c.sections).map((s) => [s.id, s]));
  for (const q of questions) {
    const scopedSections = q.sectionIds.map((id: string) => sectionsById.get(id)).filter(Boolean) as ScholarSection[];
    const reads = [...new Set(scopedSections.flatMap((s) => Array.from({ length: s.endPage - s.startPage + 1 }, (_, i) => s.startPage + i)))].sort((a, b) => a - b);
    packets.push({
      role: "assessment",
      id: `exam:question:${q.id}`,
      instruction: "Review this exam question before presentation. Check source grounding, clear wording, unique key, fair distractors, and rubric. Do not leak answer keys or rubrics.",
      reads,
      views: [],
      cropIds: [],
      payload: {
        question: q,
        sourceScope: exam.scope,
      },
    });
  }
  packets.push({
    role: "teaching",
    id: "exam:form",
    instruction: "Review the whole exam form for coverage, balance, and cues across questions. Do not require source text.",
    reads: [],
    views: [],
    cropIds: [],
    payload: {
      questions: questions.map((q) => ({
        id: q.id,
        format: q.format,
        prompt: q.prompt,
        maxPoints: q.maxPoints,
        sectionIds: q.sectionIds,
        dimensions: q.dimensions,
        claim: q.claim,
      })),
      blueprint: examBlueprint(exam, questions),
    },
  });
  return packets;
}

export function planTutorExplanationPacket(lesson: { id: string; title: string; markdown: string; sourcePages: number[]; keyPoints: string[] }): ReviewPacket {
  return {
    role: "teaching",
    id: `tutor:explanation:${lesson.id}`,
    instruction: "Review this Tutor explanation against its source pages. Check clarity, correctness, terminology, and intermediate reasoning.",
    reads: lesson.sourcePages,
    views: [],
    cropIds: [],
    payload: {
      explanation: { id: lesson.id, title: lesson.title, markdown: lesson.markdown },
      sourcePages: lesson.sourcePages,
      keyPoints: lesson.keyPoints,
    },
  };
}


Wall time: 0.08 seconds

/**
 * Question-engine thresholds, enforced when a form is frozen.
 *
 * These are the mechanically checkable parts of the engine. They do not make an
 * exam good, but they make the cheapest ways of making it bad impossible: a
 * two-option coin flip, a catch-all option that tests bookkeeping, a distractor
 * that diagnoses nothing, a holistic one-line rubric, or an all-recognition
 * paper that never asks the learner to generate anything.
 */
const MIN_MCQ_OPTIONS = 3;
const MIN_RUBRIC_CRITERIA = 2;
const MIXED_FORM_THRESHOLD = 4;
const MAX_RECOGNITION_SHARE = 0.7;
const CATCH_ALL_OPTION = /\b(all|none|both|any|either|neither)\s+of\s+(the\s+)?(above|these|them|the\s+others)\b/i;

/** What a frozen form actually covers, reported back so weak coverage is visible. */
export type ExamBlueprint = {
  questionCount: number;
  totalPoints: number;
  openPoints: number;
  recognitionShare: number;
  sectionsScoped: number;
  sectionsSampled: number;
  dimensions: string[];
};

export function examBlueprint(exam: ScholarExam, questions: ExamQuestion[]): ExamBlueprint {
  const totalPoints = questions.reduce((sum, question) => sum + question.maxPoints, 0);
  const openPoints = questions
