        );
        continue;
      }
      let result = await reviewOne(
        {
          ...options,
          packet: item,
          assignment: item,
          onProgress: (event) => {
            if (event.stage !== "complete") report({ ...event, batch: finished, batches: packets.length });
          },
        },
        item.role,
      );
      // L2: retry failed packet once within the same pass
      if (result.failure && !options.signal?.aborted) {
