  const privateExamResponse = "PRIVATE_EXAM_RESPONSE_X9";
  let editorFactory;
  const runtime = createExtensionRuntime();
  installRuntime(runtime, branch);
  const loaded = await loadExtensions([extensionPath], root, undefined, runtime);
  check(
    "production extension loader",
    loaded.errors.length === 0 && loaded.extensions.length === 1,
    loaded.errors.length ? loaded.errors.map((item) => item.error).join("; ") : extensionPath,
  );
  if (loaded.errors.length || loaded.extensions.length !== 1) {
    throw new Error("Scholar could not be loaded.");
  }

  const context = {
    cwd: root,
    model: { id: "ui-fixture", provider: "fixture", api: "openai-responses", name: "UI fixture", input: ["text", "image"], reasoning: false, contextWindow: 262144, maxTokens: 16384 },
    // Exercise the production review preflight without a network/model account.
    modelRegistry: { complete: async (model, review) => {
      const prompt = review.messages[0].content;
      let content = [{ type: "text", text: JSON.stringify({ status: "pass", findings: [] }) }], stopReason = "stop";
      if (review.messages.length === 1 && /Required read_source pages: 1\./.test(prompt)) {
        content = [{ type: "toolCall", id: "read-ui", name: "read_source", arguments: { startPage: 1, endPage: 1 } }]; stopReason = "toolUse";
      } else if (review.messages.length === 1 && /Required view_source pages: 1\./.test(prompt)) {
        content = [{ type: "toolCall", id: "view-ui", name: "view_source", arguments: { page: 1 } }]; stopReason = "toolUse";
      }
      return { role: "assistant", content, stopReason, api: model.api, provider: model.provider, model: model.id, timestamp: Date.now(), usage: { input: 100, output: 100, cacheRead: 0, cacheWrite: 0 } };
    } },
    hasUI: true,
    isIdle: () => true,
    abort: async () => {},
    sessionManager: {
      getSessionId: () => "scholar-ui-contract",
      getSessionFile: () => join(root, "session.jsonl"),
      getEntries: () => branch,
      getBranch: () => branch,
    },
    ui: {
      notify: (message, level) => notifications.push({ message, level }),
      setStatus: () => {},
      setWorkingMessage: () => {},
      setEditorText: () => {},
      setEditorComponent: (factory) => { editorFactory = factory; },
      getEditorComponent: () => editorFactory,
      editor: async () => { throw new Error("Exam must not use the Pi editor"); },
      confirm: async () => true,
      select: async (_title, options) => options[0],
    },
  };
  const extension = loaded.extensions[0];
  for (const handler of extension.handlers.get("session_start") || []) {
    await handler({}, context);
  }
  const command = extension.commands.get("scholar");
  await command.handler(`obsidian "${obsidian}"`, context);
  await command.handler(`library "${library}"`, context);
  await command.handler('open "Synthetic Scholar Book.pdf"', context);

  const definition = extension.tools.get("scholar")?.definition;
  if (!definition) throw new Error("Scholar tool did not activate after opening the book.");

