      metadata: { title: "Engine Contract Fixture" },
      chapters: [{
        number: "1",
        sections: [{
          id: "section-1",
          number: "1.1",
          title: "Identity",
          order: 1,
          startPage: 1,
          endPage: 2,
          transcript: [],
        }],
      }],
    };
    const section = book.chapters[0].sections[0];
    const exam = {
      id: "exam-1",
      status: "draft",
      scope: { description: "fixture scope", chapterIds: [], sectionIds: [] },
    };
    const tutor = {
      id: "tutor-1",
      scope: { description: "fixture scope", chapterIds: [], sectionIds: [] },
      transcript: [],
    };
