import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
import { createRequire } from "node:module";
import { extensionPath, piPackageRoot, jitiPath, resolvePiDependency, sdkAliases } from "../../../.pi/agent/extensions/scholar/tests/sdk.mjs";

const extension = dirname(extensionPath);
const piRequire = createRequire(join(piPackageRoot, "package.json"));
const { createJiti } = await import(pathToFileURL(jitiPath).href);
const jiti = createJiti(import.meta.url, {
  moduleCache: false,
  alias: {
    ...sdkAliases,
    "@earendil-works/pi-coding-agent": join(piPackageRoot, "dist", "index.js"),
    "@earendil-works/pi-tui": piRequire.resolve("@earendil-works/pi-tui"),
    typebox: piRequire.resolve("typebox"),
  },
});
const mod = (name) => jiti.import(join(extension, name));
const { marked } = await import(pathToFileURL(piRequire.resolve("marked")).href);
const { renderSection } = await mod("render/section.ts");
const { renderExam, renderExamAnswerKey } = await mod("render/assessment.ts");
const { renderBook, renderChapter, renderScholarHome } = await mod("render/navigation.ts");
const { sectionNotePath, snapshotAssetPath } = await mod("obsidian-paths.ts");

const now = "2026-09-16T12:00:00.000Z";
const config = { schemaVersion: 3, obsidianRoot: join(import.meta.dir, "vault"), libraryRoot: join(import.meta.dir, "library"), stateRoot: join(import.meta.dir, "state"), updatedAt: now };
const snapshot = { id: "figure-flux", page: 2, caption: "Figure 2.4: field lines through a closed surface, with flux arrows normal to the boundary.",
  assetFile: "figure-flux.png", sha256: "a".repeat(64), crop: { x: 120, y: 220, width: 900, height: 420, canvasWidth: 1800, canvasHeight: 2400 }, createdAt: now };
const lessonMarkdown = [
  "### What Gauss's law actually fixes",
  "",
  "The divergence of a field at a point measures how much it spreads from that point rather than merely passing through it. That local statement is what Gauss's law constrains.",
  "",
  "> [!scholar-equation] Key equation · Gauss's law for the electric field",
  ">",
  "> $$",
  "> \\nabla\\cdot\\mathbf E = \\frac{\\rho}{\\epsilon_0}",
  "> $$",
  ">",
  "> **Symbols**",
  ">",
  "> - $\\mathbf E$ — electric field at the point where the divergence is taken",
  "> - $\\rho$ — total charge density, bound charge included",
  "> - $\\epsilon_0$ — vacuum permittivity",
  ">",
  "> **Assumptions:** the field is differentiable at the point and the charge distribution is described by a density.",
  ">",
  "> **Meaning:** divergence is fixed locally by charge density; it says nothing about the field's curl or its value at a boundary.",
  ">",
  "> *Source: PDF page 2.*",
  "",
  `${snapshot.caption.includes("Figure 2.4") ? "" : ""}`.length ? "" : "",
  "> [!scholar-figure] Figure · PDF page 2",
  ">",
  `> ![[../Assets/${snapshot.assetFile}|640]]`,
  ">",
  "> Field lines cross the closed surface, and the arrows normal to it give the net flux the law constrains.",
  ">",
  "> *Source: Electrodynamics fixture.pdf · PDF viewer page 2.*",
  "",
  "### Why zero divergence is not zero field",
  "",
  "A region with no charge has zero divergence everywhere inside it, yet the field there can still be nonzero: a uniformly polarized slab has a divergence-free field in its interior while carrying a field of its own. Divergence and curl are independent statements, so the law alone cannot pin the field down without boundary conditions.",
  "",
  "### Apply the idea",
  "",
  "Suppose a surface encloses no net charge. Then the net flux through it is zero, while the flux through each patch need not be: inward and outward contributions cancel exactly. Reading the law as a per-patch rule is the standard misreading it forbids.",
].join("\n");
const coverage = [
  { id: "gauss-local", kind: "concept", description: "State what the divergence form of Gauss's law fixes locally", sourcePages: [2], objective: "Explain what Gauss's law does and does not determine", lessonId: "gauss", evidence: "The divergence of a field at a point measures how much it spreads from that point" },
