  { id: "gauss-figure", kind: "figure", description: "Walk through the flux arrows on the closed surface", sourcePages: [2], objective: "Explain what Gauss's law does and does not determine", lessonId: "gauss", evidence: "Field lines cross the closed surface", snapshotId: snapshot.id },
];
const objective = "Explain what Gauss's law does and does not determine";
const section = {
  id: "section-1", number: "2.4", title: "Gauss's law and divergence", order: 4, startPage: 2, endPage: 2, status: "learning",
  objectives: [objective], coveredObjectives: [], requiredChecks: ["conceptual"], objectiveChecks: [{ objective, checks: ["conceptual"] }],
  synthesis: "Divergence fixes the field's local spreading, not the field itself; boundary conditions and curl supply the rest.",
  keyPoints: ["Divergence is fixed by charge density, not by the field's value."], misconceptions: [], attempts: [], snapshots: [snapshot],
  figureCoverage: { pages: [{ page: 2, read: true, viewed: { width: 900, height: 1200 }, candidates: ["Figure 2.4"],
    review: { page: 2, observation: "Field lines cross a closed surface with outward arrows on the right half.", figures: [{ label: "Figure 2.4", snapshotId: snapshot.id }] } }] },
  learnQuality: { version: 1, coverage, reviews: [
    { role: "source", contentHash: "b".repeat(64), sourceHash: "c".repeat(64), model: "fixture/model", createdAt: now, status: "pass", findings: [] },
    { role: "teaching", contentHash: "b".repeat(64), sourceHash: "c".repeat(64), model: "fixture/model", createdAt: now, status: "pass", findings: [] },
    { role: "visual", contentHash: "b".repeat(64), sourceHash: "c".repeat(64), model: "fixture/model", createdAt: now, status: "pass", findings: [] },
  ] },
  transcript: [{ id: "gauss", kind: "assistant", markdown: lessonMarkdown, createdAt: now,
    lesson: { title: "Gauss's law and divergence", objectives: [objective], keyPoints: ["Divergence is fixed by charge density, not by the field's value."], sourcePages: [2], contentHash: "d".repeat(64), sourceHash: "c".repeat(64), embeddedSnapshotIds: [snapshot.id], keyEquationIds: ["gauss"] } },
    { id: "q1", kind: "assistant", markdown: "**Which quantity does the divergence form fix at a point?**", createdAt: now },
  ],
  attempts: [{ id: "a1", kind: "conceptual", format: "quiz", outcome: "correct", question: "Which quantity does the divergence form fix at a point?",
    correctAnswer: "the spread of the field from that point", feedback: "Correct: divergence describes local spreading, so a zero divergence does not force a zero field.",
    grounding: { purpose: "mastery", competency: objective, requiredEvidence: ["Names the local spreading of the field"], sourcePages: [2], basis: [{ kind: "objective", value: objective, supports: [1] }] } }],
  createdAt: now, updatedAt: now,
};
const chapter = { id: "chapter-2", number: "2", order: 2, title: "Electrostatics", startPage: 1, endPage: 40, status: "learning", sections: [section] };
const examQuestions = [{
  id: "q1", sectionIds: ["section-1"], claim: "Divergence is a local statement", requiredEvidence: ["Names the divergence as local spreading"], dimensions: ["conceptual"],
  prompt: "A region contains no charge. What does Gauss's law in divergence form tell you about the field there?", explanation: "It fixes the divergence, not the field: a divergence-free field can still be nonzero.",
  maxPoints: 2, format: "multiple-choice",
  options: [{ value: "div", label: "The divergence vanishes, so the field may still be nonzero", misconception: "none needed" },
    { value: "zero", label: "The field itself vanishes everywhere", misconception: "Confuses zero divergence with zero field" },
    { value: "flux", label: "The net flux through every closed surface becomes negative", misconception: "Sign error in the flux reading" }],
  correctAnswer: "div",
}];
const exam = { id: "exam-1", title: "Electrostatics checkpoint", status: "graded", scope: { chapterIds: ["chapter-2"], sectionIds: ["section-1"], description: "Chapter 2" },
  questions: examQuestions, snapshots: [], images: [], rawResponses: [], itemResults: [
    { questionId: "q1", earnedPoints: 0, maxPoints: 2, outcome: "incorrect", feedback: "The divergence vanishes, but the field need not.",
      firstDecisiveError: "Zero divergence was read as zero field.", correctReasoning: "Divergence and curl are independent, so a divergence-free field can be nonzero.",
      transferableLesson: "Read Gauss's law as a local constraint on spreading." }],
  earnedPoints: 0, percent: 0, createdAt: now, updatedAt: now, examNoteClaims: [] };
const book = { schemaVersion: 3, revision: 0, id: "e".repeat(64), instanceId: "preview", currentSectionId: section.id, currentExamId: exam.id,
  source: { absolutePath: "C:/library/Electrodynamics fixture.pdf", relativePath: "Electrodynamics fixture.pdf", fileName: "Electrodynamics fixture.pdf", format: "pdf",
    fingerprint: { sha256: "c".repeat(64), size: 1024, mtimeMs: 1 } },
  metadata: { title: "Electrodynamics fixture", authors: ["A. Source"], pageCount: 40 }, outlineStatus: "ready", noteDirectory: "Electrodynamics fixture",
  chapters: [chapter], exams: [exam], tutorSessions: [], createdAt: now, updatedAt: now };

const sectionNote = renderSection(config, book, chapter, section);
const examNote = renderExam(config, book, exam);
const answerKey = renderExamAnswerKey(config, book, exam);
const bookNote = renderBook(config, book);
const chapterNote = renderChapter(config, book, chapter);
const homeNote = renderScholarHome(config, [book]);
await writeFile(join(import.meta.dir, "notes.json"), JSON.stringify({ sectionNote, examNote, answerKey, bookNote, chapterNote, homeNote }, null, 1));
console.log("section:", sectionNote.length, "exam:", examNote.length, "key:", answerKey.length, "book:", bookNote.length);
console.log(sectionNote.split("\n").slice(0, 12).join("\n"));

