  for (let index = 0; index < lines.length;) {
    const header = /^> \[!([\w-]+)\]([+-]?)\s*(.*)$/.exec(lines[index]);
    if (header) {
      const body = [];
      index++;
      while (index < lines.length && lines[index].startsWith(">")) { body.push(lines[index].replace(/^> ?/, "")); index++; }
