const escapeHtml = (value) => value.replace(/[&<>]/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[character]));

function inlineMath(text) {
  return text
    .replace(/!\[\[([^\]|]+)(?:\|\d+)?\]\]/g, () => `<span class="internal-embed image-embed"><img src="${figureData}" alt="Figure 2.4"></span>`)
    .replace(/\$([^$\n]+)\$/g, (_match, tex) => `<span class="math-inline">${escapeHtml(tex)}</span>`)
    .replace(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g, (_match, target, label) => `<a class="internal-link" href="#">${escapeHtml(label || target)}</a>`);
}

/** Obsidian's callout DOM, so scholar.css selectors apply exactly as they do in the app. */
function calloutHtml(type, title, body) {
  const content = [...body.matchAll(/^\s*(\$\$[\s\S]*?\$\$)/gm)];
  const html = content.length
    ? `<div class="math-block">${escapeHtml(content[0][1].replace(/^\s*|\s*$/g, ""))}</div>` + marked.parse(inlineMath(body.replace(content[0][1], "")), { gfm: true })
    : marked.parse(inlineMath(body), { gfm: true });
  return `<div class="callout" data-callout="${type}"><div class="callout-title"><div class="callout-icon"></div><div class="callout-title-inner">${escapeHtml(title)}</div></div><div class="callout-content">${html}</div></div>`;
}

function bodyHtml(markdown) {
  const lines = markdown.split("\n");
  const out = [];
  let plain = [];
  const flush = () => { if (plain.length) { out.push(marked.parse(inlineMath(plain.join("\n")), { gfm: true, breaks: false })); plain = []; } };
  for (let index = 0; index < lines.length;) {
    const header = /^> \[!([\w-]+)\]([+-]?)\s*(.*)$/.exec(lines[index]);
    if (header) {
      const body = [];
      index++;
      while (index < lines.length && lines[index].startsWith(">")) { body.push(lines[index].replace(/^> ?/, "")); index++; }
      flush();
      out.push(calloutHtml(header[1].toLowerCase(), header[3], body.join("\n").replace(/\n+$/, "")));
      continue;
    }
    plain.push(lines[index++]);
  }
  flush();
  return out.join("\n");
}

