    const embed = figure?.querySelector(".image-embed img");
    const bar = document.querySelector(".scholar-progress");
    const score = document.querySelector(".scholar-score");
    const px = (value) => Number.parseFloat(value || "0");
    return {
      equation: { present: Boolean(equation), borderWidth: px(style(equation)?.borderInlineStartWidth), borderColor: style(equation)?.borderInlineStartColor,
        mathAlign: style(math)?.textAlign, symbols: symbols.length, labelColor: style(equation?.querySelector("strong"))?.color, titleColor: style(equation?.querySelector(".callout-title-inner"))?.color },
      figure: { present: Boolean(figure), imageBorder: px(style(embed)?.borderTopWidth), radius: style(embed)?.borderTopLeftRadius, background: style(embed)?.backgroundColor,
