      status: { present: Boolean(status), marginTop: style(status)?.marginBlockStart, fontSize: style(status?.querySelector(".callout-title-inner"))?.fontSize, color: style(status?.querySelector(".callout-title-inner"))?.color },
      progress: bar ? { present: true, height: px(style(bar)?.height), radius: style(bar)?.borderTopLeftRadius, track: style(bar)?.backgroundColor,
        fill: style(bar.querySelector("span"))?.backgroundColor, fillWidth: px(style(bar.querySelector("span"))?.width), trackWidth: px(style(bar)?.width) } : { present: false },
      score: score ? { present: true, padding: style(score)?.padding, radius: style(score)?.borderTopLeftRadius, background: style(score)?.backgroundColor, inline: style(score)?.display } : { present: false },
      bodyColor: getComputedStyle(document.body).color,
      heading: style(document.querySelector(".markdown-preview-view h2"))?.fontSize,
    };
  });
  const shot = await tab.screenshot();
  await tab.close();
  return { report, shot };
}
