async function inspect(name, file, width, dark) {
  const tab = await browser.open({ name, url: `file:///${dir}/${file}`, viewport: { width, height: 1100 } });
  await tab.waitForSelector(".callout[data-callout='scholar-equation']");
  const report = await tab.evaluate(() => {
    const style = (element) => element ? getComputedStyle(element) : null;
    const px = (value) => Number.parseFloat(value || "0");
    const equation = document.querySelector(".callout[data-callout='scholar-equation']");
    const figure = document.querySelector(".callout[data-callout='scholar-figure']");
    const embed = figure?.querySelector(".image-embed");
    const bars = [...document.querySelectorAll(".scholar-progress")].map((bar) => {
      const span = bar.querySelector("span");
      return { percent: bar.getAttribute("style"), fillPercent: Math.round(px(style(span).width) / px(style(bar).width) * 100), height: px(style(bar).height) };
    });
    const score = document.querySelector(".scholar-score");
    return {
      bodyText: style(document.body).color, bodyBackground: style(document.body).backgroundColor,
      equation: { border: `${px(style(equation)?.borderInlineStartWidth)}px ${style(equation)?.borderInlineStartColor}`, mathAlign: style(equation?.querySelector(".math-block"))?.textAlign,
        symbols: equation?.querySelectorAll(".callout-content li").length, collapsedRecord: Boolean(document.querySelector(".callout.is-collapsed")) },
      figure: { frameBorder: px(style(embed)?.borderTopWidth), radius: style(embed)?.borderTopLeftRadius, background: style(embed)?.backgroundColor,
        imageCentered: (() => { const img = figure?.querySelector("img"); const frame = embed?.getBoundingClientRect(); const box = img?.getBoundingClientRect(); return frame && box ? Math.round((box.left - frame.left) - (frame.right - box.right)) : null; })() },
      progress: bars, score: { present: Boolean(score), background: style(score)?.backgroundColor, display: style(score)?.display },
    };
  });
  const shot = await tab.screenshot();
  await tab.close();
  return { report, shot, dark };
}
