let s = await Bun.file(p).text();
const oldBody = s.slice(s.indexOf("function bodyHtml(markdown) {"), s.indexOf("const CSS_VARS_LIGHT"));
if (!oldBody) throw new Error("bodyHtml not found");
const newBody = `function bodyHtml(markdown) {
  const lines = markdown.split("\\n");
  const out = [];
  let plain = [];
  const flush = () => { if (plain.length) { out.push(marked.parse(inlineMath(plain.join("\\n")), { gfm: true, breaks: false })); plain = []; } };
  for (let index = 0; index < lines.length;) {
    const header = /^> \\[!([\\w-]+)\\]([+-]?)\\s*(.*)$/.exec(lines[index]);
    if (header) {
      const body = [];
      index++;
      while (index < lines.length && lines[index].startsWith(">")) { body.push(lines[index].replace(/^> ?/, "")); index++; }
      flush();
      // Obsidian nests callouts inside callouts; recursion keeps the preview faithful.
      out.push(calloutHtml(header[1].toLowerCase(), header[3], body.join("\\n").replace(/\\n+$/, ""), header[2] === "-"));
      continue;
    }
    plain.push(lines[index++]);
