// Throwaway cost measurement for the real Griffiths E&M 1.2 section: how many crew packets the
// new planner produces and what evidence each one carries. Deleted after the numbers are reported.
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { createRequire } from "node:module";

const here = dirname(fileURLToPath(import.meta.url));
const EXT = "C:/Users/basam/.pi/agent/extensions/scholar";
const VAULT = "C:/Users/basam/Desktop/Basam's_Vault";
const require = createRequire(join(EXT, "package.json"));
const sdk = await import(pathToFileURL(join(EXT, "tests", "sdk.mjs")).href);
const { createJiti } = await import(pathToFileURL(sdk.jitiPath).href);
const jiti = createJiti(import.meta.url, {
  moduleCache: false,
  alias: {
    ...sdk.sdkAliases,
    "@earendil-works/pi-coding-agent": join(sdk.piPackageRoot, "dist", "index.js"),
    "@earendil-works/pi-tui": sdk.resolvePiDependency("@earendil-works/pi-tui"),
    typebox: sdk.resolvePiDependency("typebox"),
  },
});
const mod = (name) => jiti.import(join(EXT, name));
const storage = await mod("storage.ts");
const { planReviewAssignments, currentReviewSnapshots } = await mod("review-layer.ts");
const { readFile } = await import("node:fs/promises");

const config = { schemaVersion: 3, obsidianRoot: VAULT, libraryRoot: join(VAULT, ".."), stateRoot: join(here, "state"), updatedAt: "2026-09-16T12:00:00.000Z" };
const books = await storage.listBookStates(config);
const target = books.find((book) => /Griffiths/i.test(book.metadata.title));
if (!target) throw new Error(`No Griffiths book among ${books.length} book(s): ${books.map((book) => book.metadata.title).join(", ")}`);
const section = target.chapters.flatMap((chapter) => chapter.sections).find((item) => /1\.2/.test(item.number || "") || /Differential Calculus/i.test(item.title));
if (!section) throw new Error("Section 1.2 not found");
const sourceHash = target.source.fingerprint.sha256;
const crops = currentReviewSnapshots(section, sourceHash);
const plan = planReviewAssignments(section, sourceHash, 300_000);
const byRole = {};
for (const packet of plan) {
  const role = byRole[packet.role] || (byRole[packet.role] = { packets: 0, reads: 0, crops: 0, views: 0, payloadChars: 0 });
  role.packets++;
  role.reads += packet.reads.length;
  role.crops += packet.cropIds.length;
  role.views += packet.views.length;
  role.payloadChars += JSON.stringify(packet.payload).length;
}
const topics = (section.transcript || []).filter((entry) => entry.lesson).flatMap((entry) => (entry.markdown.match(/^###\s+\S/gm) || []).length);
const legacy = { source: Math.ceil((section.endPage - section.startPage + 1) / 4), teaching: topics + 1 };
console.log(JSON.stringify({
  section: `${section.number} ${section.title}`, pages: `${section.startPage}-${section.endPage}`, topics, currentCrops: crops.length,
  noteBytes: (await readFile(join(VAULT, "Scholar", ...(target.noteDirectory || "").split(/[\\/]/).filter(Boolean), "Sections", `${(section.number || section.id).replace(/[^\w.\- ]/g, "")} - ${section.title}.md`), "utf8")).length,
  packets: plan.length, byRole,
  totalImages: plan.reduce((sum, packet) => sum + packet.cropIds.length + packet.views.length, 0),
  totalReadPages: plan.reduce((sum, packet) => sum + packet.reads.length, 0),
  payloadChars: plan.reduce((sum, packet) => sum + JSON.stringify(packet.payload).length, 0),
  preChangeEstimate: { sourcePackets: legacy.source, teachingPackets: legacy.teaching, visualPackets: topics + 1, total: legacy.source + legacy.teaching + topics + 1 },
  packetIds: plan.map((packet) => `${packet.id}${packet.crops ? "" : ""}${packet.cropIds.length ? `(${packet.cropIds.length} crops)` : ""}`),
}, null, 1));

