    },
    {
      "path": "tests/verify-scholar-projection.mjs",
      "description": "Pins collapsedRecord framing (66-67), exactly one generated marker per note (87), byte-identical re-render with handwritten tails (84-95), and that refresh never rewrites a section note (98-107)."
    },
    {
      "path": "tests/verify-scholar-note-design.mjs",
