// Throwaway: regenerate the real Griffiths E&M section 1.3 note through the extension's own
// writer (`writeNoteBook`), then prove the round trip: section metadata, transcript entries and
// question chunks must be identical before and after, and the pre-lesson area must collapse.
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const EXT = "C:/Users/basam/.pi/agent/extensions/scholar";
const BOOK_ID = "987099eccd1cb67fc2ea5565ff193a37245576730f944e349b11174900f63826";
const SECTION_ID = "chapter-001-section-003";

const sdk = await import(pathToFileURL(join(EXT, "tests", "sdk.mjs")).href);
const { createJiti } = await import(pathToFileURL(sdk.jitiPath).href);
const jiti = createJiti(import.meta.url, {
  moduleCache: false,
  alias: {
    ...sdk.sdkAliases,
    "@earendil-works/pi-coding-agent": join(sdk.piPackageRoot, "dist", "index.js"),
    "@earendil-works/pi-tui": sdk.resolvePiDependency("@earendil-works/pi-tui"),
    typebox: sdk.resolvePiDependency("typebox"),
  },
});

const { listBookStates } = await jiti.import(join(EXT, "storage.ts"));
const { writeNoteBook } = await jiti.import(join(EXT, "note-storage.ts"));
const { readDetails, readTranscript, questionChunks } = await jiti.import(join(EXT, "note-records.ts"));
const { sectionNotePath } = await jiti.import(join(EXT, "obsidian-paths.ts"));

const raw = JSON.parse(await readFile(join(process.env.USERPROFILE, ".pi", "agent", "scholar", "config.json"), "utf8"));
const config = { schemaVersion: 3, obsidianRoot: raw.obsidianRoot, stateRoot: join(process.env.USERPROFILE, ".pi", "agent", "scholar"), updatedAt: new Date().toISOString() };

const books = await listBookStates(config);
const book = books.find((item) => item.id === BOOK_ID);
if (!book) throw new Error(`Real book ${BOOK_ID} was not found among ${books.length} authority notes.`);
const chapter = book.chapters.flatMap((item) => item.sections.map((section) => ({ chapter: item, section }))).find((item) => item.section.id === SECTION_ID);
if (!chapter) throw new Error(`Section ${SECTION_ID} is absent from the real book.`);
const notePath = sectionNotePath(config, book, chapter.chapter, chapter.section);

const snapshot = async (text) => {
  const details = readDetails(text, "section");
  const transcript = readTranscript(text);
  const questions = questionChunks(text);
  const start = text.indexOf("<!-- scholar:generated:start -->");
  const lesson = text.indexOf("\n## Lesson");
  return {
    details: JSON.stringify(details ?? null),
    transcriptCount: transcript.length,
    transcriptHashes: transcript.map((chunk) => chunk.markdown.length),
    questionCount: questions.length,
    preLesson: start >= 0 && lesson > start
      ? text.slice(start + "<!-- scholar:generated:start -->".length, lesson).split(/\r?\n/).filter((line) => line.trim())
      : null,
  };
};

const before = await readFile(notePath, "utf8");
const beforeState = await snapshot(before);
console.log("BEFORE pre-lesson blocks:", JSON.stringify(beforeState.preLesson, null, 1));
console.log(`BEFORE transcript entries: ${beforeState.transcriptCount}, questions: ${beforeState.questionCount}, details: ${beforeState.details.length} chars`);

await writeNoteBook(config, book, book.revision);

const after = await readFile(notePath, "utf8");
const afterState = await snapshot(after);
console.log("AFTER pre-lesson blocks:", JSON.stringify(afterState.preLesson, null, 1));
console.log(`AFTER transcript entries: ${afterState.transcriptCount}, questions: ${afterState.questionCount}, details: ${afterState.details.length} chars`);

const problems = [];
if (afterState.details !== beforeState.details) problems.push("section details JSON changed");
if (afterState.transcriptCount !== beforeState.transcriptCount) problems.push("transcript entry count changed");
if (JSON.stringify(afterState.transcriptHashes) !== JSON.stringify(beforeState.transcriptHashes)) problems.push("transcript entry text changed");
if (afterState.questionCount !== beforeState.questionCount) problems.push("question count changed");
const tailBefore = before.slice(before.indexOf("<!-- scholar:generated:end -->"));
const tailAfter = after.slice(after.indexOf("<!-- scholar:generated:end -->"));
if (tailBefore !== tailAfter) problems.push("reader tail after the end marker changed");
console.log(problems.length ? `PROBLEMS: ${problems.join("; ")}` : "ROUND TRIP OK: metadata, entries, questions and reader tail identical.");
process.exitCode = problems.length ? 1 : 0;

