// Throwaway: what does the audit-as-you-go model actually schedule for the real sections?
// Counts units, packets, page reads, crops and payload size from the shipped planners.
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const EXT = "C:/Users/basam/.pi/agent/extensions/scholar";
const BOOK_ID = "987099eccd1cb67fc2ea5565ff193a37245576730f944e349b11174900f63826";

const sdk = await import(pathToFileURL(join(EXT, "tests", "sdk.mjs")).href);
const { createJiti } = await import(pathToFileURL(sdk.jitiPath).href);
const jiti = createJiti(import.meta.url, {
  moduleCache: false,
  alias: {
    ...sdk.sdkAliases,
    "@earendil-works/pi-coding-agent": join(sdk.piPackageRoot, "dist", "index.js"),
    "@earendil-works/pi-tui": sdk.resolvePiDependency("@earendil-works/pi-tui"),
    typebox: sdk.resolvePiDependency("typebox"),
  },
});

const { listBookStates } = await jiti.import(join(EXT, "storage.ts"));
const { lessonReviewUnits } = await jiti.import(join(EXT, "lesson.ts"));
const { planLessonUnitPackets } = await jiti.import(join(EXT, "learn-review.ts"));

const raw = JSON.parse(await readFile(join(process.env.USERPROFILE, ".pi", "agent", "scholar", "config.json"), "utf8"));
const config = { schemaVersion: 3, obsidianRoot: raw.obsidianRoot, stateRoot: join(process.env.USERPROFILE, ".pi", "agent", "scholar"), updatedAt: new Date().toISOString() };
const book = (await listBookStates(config)).find((item) => item.id === BOOK_ID);
if (!book) throw new Error("real book not found");
const sourceHash = book.source.fingerprint.sha256;

for (const chapter of book.chapters) {
  for (const section of chapter.sections) {
    const units = lessonReviewUnits(section, sourceHash);
    if (!units.length) continue;
    const roles = {};
    let packets = 0, reads = 0, crops = 0, chars = 0, visualUnits = 0;
    for (const unit of units) {
      if (unit.roles.includes("visual")) visualUnits++;
      for (const packet of planLessonUnitPackets(unit, section, sourceHash, undefined)) {
        packets++;
        roles[packet.role] = (roles[packet.role] || 0) + 1;
        reads += packet.reads.length;
        crops += packet.cropIds.length;
        chars += JSON.stringify(packet.payload).length;
      }
    }
    const pages = `${section.startPage}-${section.endPage}`;
    console.log(`${section.number} ${section.title}`);
    console.log(`  pages ${pages} · saved lesson units ${units.length} (${visualUnits} with crops) · lesson entries: ${units.map(u => u.entryId).join(", ") || "none"}`);
    console.log(`  audit packets ${packets} (${Object.entries(roles).map(([r, n]) => `${r}:${n}`).join(" ")}) · page reads ${reads} · crops ${crops} · payload ${Math.round(chars / 1024)} KiB`);
  }
}

